function getAggregationValue() {
    let employeeId = source.ExternalId;
    let correlationValue = employeeId;
    if (employeeId.startsWith('20')) {
    // Eigen medewerkers (2039070 -> 39070)
    // verwijder de eerste '2' en daarna alle voorloopnullen
        correlationValue =  '000' + employeeId.slice(2);
    } else if (employeeId.startsWith('21')) {
         correlationValue = '8000' + employeeId.slice(2);
    }  else if (employeeId.startsWith('22')) {
         correlationValue = '9000' + employeeId.slice(2);
    }
    return correlationValue;
}
